  selector: 'app-root',
  template: '',
  styleUrls: []
})
export class AppComponent implements OnInit {
  counter: number = 0;
  expensiveResult: number = 0;

  ngOnInit() {
    this.counter = 0;
    this.expensiveResult = this.expensiveComputation(this.counter);
  }

  expensiveComputation(base: number): number {
    // Simulate expensive computation
    let result = 0;
    for (let i = 0; i < 1000000000; i++) {
      result += base + i;
    }
    return result;
  }

  incrementCounter() {
    this.counter++;
    this.expensiveResult = this.expensiveComputation(this.counter);
  }
}

